with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الدوران العام والمناخ الإقليمي والتذبذبات المناخية','الدوران العام وأحزمة الرياح والرياح الموسمية وأنماط ENSO وNAO وMJO ومناخ الأقاليم وتصنيفها.',19,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الدوران العام والمناخ الإقليمي',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'مناخ الأقاليم والأنماط المحلية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('general-circulation-atmosphere','الدوران العام للغلاف الجوي','الخلايا الدورانية الكبرى وتوزيع الضغط والطاقة على الكوكب.','{"blocks":[{"type":"text","text":"ينشأ الدوران العام من التوزيع غير المتساوي للطاقة الشمسية بين خط الاستواء والقطبين ومن دوران الأرض."},{"type":"text","text":"ينقل الغلاف الجوي الطاقة والزخم والرطوبة بين العروض الجغرافية عبر أنظمة واسعة النطاق."},{"type":"text","text":"يمثل نموذج الخلايا الثلاث تبسيطاً للدوران المتوسط بخلايا هادلي وفيريل والخلية القطبية في كل نصف كرة."},{"type":"text","text":"تتميز خلية هادلي بصعود الهواء قرب نطاق التقارب المداري وهبوطه في العروض شبه المدارية، مع تغيرات موسمية في موقعها."},{"type":"text","text":"تصف خلية فيريل دوراناً متوسطاً في العروض الوسطى، وتتأثر بالدوامات العابرة والأنظمة الجوية."},{"type":"text","text":"تسهم الخلية القطبية في الدوران بين العروض العليا، وترتبط برياح شرقية قطبية في المتوسط المناخي."},{"type":"text","text":"تتشكل أحزمة الضغط السطحي من أنماط الصعود والهبوط الواسعة، لكنها تتغير موسمياً ومكانياً."},{"type":"text","text":"تسهم الدوامات العابرة والمنخفضات والمرتفعات في نقل الحرارة نحو القطبين وتعديل الدوران المتوسط."},{"type":"text","text":"تتغير مواقع أحزمة الضغط والرياح مع الفصول بسبب ميل محور الأرض واختلاف التسخين بين اليابسة والماء."},{"type":"text","text":"لا تمثل الخلايا الثلاث مسارات ثابتة لكل حزمة هوائية؛ بل هي نموذج متوسط لتفسير الدوران الكوكبي."},{"type":"text","text":"مثال: انتقال نطاق التقارب المداري موسمياً يغير أنماط المطر والرياح في مناطق مدارية واسعة."},{"type":"callout","text":"خلاصة: الدوران العام إطار أساسي لفهم أنماط الرياح والمناخ وتوزيع الهطول على الأرض."}]}',1160,55,'["شرح خلايا الدوران الكبرى","فهم نقل الطاقة والزخم","تمييز أحزمة الضغط والرياح"]','الدوران العام والمناخ الإقليمي'),
('global-wind-belts-and-trade-winds','أحزمة الرياح العالمية والرياح التجارية والغربية','توزيع الرياح السطحية والعليا وعلاقة الضغط بدوران الأرض.','{"blocks":[{"type":"text","text":"تنتج أحزمة الرياح العالمية من تفاعل توزيع الضغط مع دوران الأرض والتسخين غير المتساوي."},{"type":"text","text":"تهب الرياح التجارية من نطاقات الضغط شبه المداري نحو منطقة الضغط المنخفض الاستوائي، وتنحرف بفعل كوريوليس."},{"type":"text","text":"تظهر الرياح التجارية شمال خط الاستواء غالباً من الشمال الشرقي، وجنوبه غالباً من الجنوب الشرقي."},{"type":"text","text":"تسود الرياح الغربية في العروض الوسطى، وتؤثر في انتقال المنخفضات والجبهات من الغرب إلى الشرق في المتوسط."},{"type":"text","text":"تظهر الرياح الشرقية القطبية في العروض العليا ضمن الدوران المتوسط حول مناطق الضغط القطبي."},{"type":"text","text":"تصف قوة كوريوليس الانحراف الظاهري للحركة بسبب دوران الأرض، وتكون صفراً عند خط الاستواء وتزداد نحو القطبين."},{"type":"text","text":"تختلف الرياح الفعلية عن أحزمة المتوسط بسبب اليابسة والمحيطات والتضاريس والأنظمة الجوية العابرة."},{"type":"text","text":"تتغير مواقع الأحزمة وشدتها موسمياً مع انتقال مناطق التسخين والضغط."},{"type":"text","text":"تؤثر حرارة سطح البحر والتباين الحراري بين القارات والمحيطات في قوة الرياح واتجاهها الإقليمي."},{"type":"text","text":"تستخدم خرائط الضغط والرياح طويلة الأمد لتحديد الأنماط المناخية السائدة."},{"type":"text","text":"مثال: قد تنحرف الرياح التجارية محلياً حول جزيرة أو سلسلة جبلية رغم اتجاهها العام المتوقع."},{"type":"callout","text":"خلاصة: الأحزمة العالمية تصف الاتجاهات المناخية العامة، بينما تحدد الظروف الإقليمية التفاصيل اليومية."}]}',1170,55,'["تحديد أحزمة الرياح","شرح الرياح التجارية والغربية","فهم تأثير كوريوليس"]','الدوران العام والمناخ الإقليمي'),
('monsoon-circulation-and-seasonal-reversal','الرياح الموسمية وانعكاس الدورة الموسمية','التباين الحراري الموسمي بين اليابسة والمحيط وتحول اتجاه الرياح والهطول.','{"blocks":[{"type":"text","text":"الرياح الموسمية نظام دوران إقليمي واسع يتسم بتغير موسمي ملحوظ في اتجاه الرياح ويرتبط بتغير توزيع الحرارة والضغط."},{"type":"text","text":"تسخن اليابسة وتبرد أسرع من المحيط، ما يغير التدرج الحراري والضغط بينهما خلال السنة."},{"type":"text","text":"في الموسم الدافئ قد يتطور ضغط منخفض حراري فوق القارة ويعزز تدفق هواء رطب من المحيط نحو اليابسة."},{"type":"text","text":"في الموسم البارد قد ينعكس التدرج ويصبح التدفق السائد من اليابسة نحو المحيط في مناطق موسمية كثيرة."},{"type":"text","text":"يسهم انتقال نطاق التقارب المداري وتغير موقعه في تنظيم موسم الأمطار الموسمية."},{"type":"text","text":"تؤثر التضاريس في رفع الهواء الرطب وتوزيع المطر، وقد تنتج فروق كبيرة بين السفوح المواجهة والمعاكسة للرياح."},{"type":"text","text":"تتغير بداية الموسم الموسمي وانسحابه من سنة إلى أخرى، ولا يحدده تاريخ ثابت في جميع المناطق."},{"type":"text","text":"تتأثر قوة الموسم الموسمي بحالة المحيطات والأنماط واسعة النطاق مثل ENSO وأنماط الضغط الإقليمية."},{"type":"text","text":"قد تحدث فترات توقف أو نشاط متقطع داخل الموسم، لذلك لا يعني بدء الموسم استمرار المطر يومياً."},{"type":"text","text":"تستخدم خرائط الرياح والرطوبة والهطول ومؤشرات الدوران لتقييم تطور النظام الموسمي."},{"type":"text","text":"مثال: تأخر تدفق الرطوبة من المحيط قد يؤخر بداية موسم الأمطار حتى إذا ارتفعت الحرارة القارية مبكراً."},{"type":"callout","text":"خلاصة: الموسمية نظام مقترن بين اليابسة والمحيط والغلاف الجوي يتغير زمنياً ومكانياً."}]}',1180,55,'["تعريف النظام الموسمي","شرح الانعكاس الموسمي للرياح","فهم دور اليابسة والمحيط"]','الدوران العام والمناخ الإقليمي'),
('enso-el-nino-la-nina','ظاهرة النينيو والنينيا ENSO','التذبذب الجنوبي وتغير حرارة المحيط الهادئ وآثارهما المناخية البعيدة.','{"blocks":[{"type":"text","text":"ENSO نمط من التباين المناخي المقترن بين المحيط والغلاف الجوي في المحيط الهادئ الاستوائي."},{"type":"text","text":"تتميز النينيو بارتفاع غير معتاد في حرارة سطح البحر في أجزاء من الهادئ الاستوائي الأوسط والشرقي وفق مؤشرات محددة."},{"type":"text","text":"تتميز النينيا ببرودة نسبية غير معتادة في المناطق نفسها مقارنة بخط الأساس المناخي."},{"type":"text","text":"يرتبط التذبذب الجنوبي بتغيرات الضغط الجوي بين مناطق من الهادئ، ويعد جزءاً جوياً من منظومة ENSO."},{"type":"text","text":"تؤثر تغيرات حرارة سطح البحر في الحمل الحراري والرياح التجارية ومواقع الهطول فوق المحيط."},{"type":"text","text":"تنتقل التأثيرات إلى مناطق بعيدة عبر أنماط الاتصال المناخي Teleconnections، لكنها تختلف باختلاف الموسم والمنطقة."},{"type":"text","text":"لا تعني النينيو أو النينيا أثراً واحداً ثابتاً لكل دولة؛ إذ تتغير الاستجابة بحسب الفصل والأنماط المناخية الأخرى."},{"type":"text","text":"تستخدم مؤشرات مثل Niño 3.4 ومؤشر التذبذب الجنوبي لتوصيف الحالة وفق تعريفات مرجعية."},{"type":"text","text":"قد تتطور الحالة خلال عدة أشهر، ويحتاج توقعها إلى نماذج محيطية-جوية ومتابعة الرصد."},{"type":"text","text":"تؤثر ENSO في احتمالات الهطول والحرارة والأعاصير في مناطق متعددة، وليس في الطقس اليومي المحدد بصورة مباشرة."},{"type":"text","text":"مثال: قد ترتبط حالة ENSO بزيادة احتمال موسم جاف في إقليم معين، لكن التوقع المحلي يحتاج معلومات إقليمية إضافية."},{"type":"callout","text":"خلاصة: ENSO نمط محيطي-جوي رئيسي يؤثر في احتمالات المناخ العالمي عبر الاقتران والاتصالات البعيدة."}]}',1190,55,'["شرح مراحل ENSO","فهم الاقتران بين المحيط والغلاف الجوي","تفسير التأثيرات المناخية الإقليمية"]','الدوران العام والمناخ الإقليمي'),
('north-atlantic-oscillation-and-arctic-oscillation','تذبذب شمال الأطلسي والتذبذب القطبي','أنماط الضغط في العروض الشمالية وتأثيرها في مسارات المنخفضات والشتاء.','{"blocks":[{"type":"text","text":"يقيس تذبذب شمال الأطلسي NAO اختلاف الضغط بين منطقة شبه مدارية شمال الأطلسي ومنطقة قرب آيسلندا وفق تعريف المؤشر."},{"type":"text","text":"تعبر المرحلة الموجبة عادة عن تدرج ضغط أقوى ورياح غربية أكثر نشاطاً فوق شمال الأطلسي، مع تغيرات إقليمية في مسارات العواصف."},{"type":"text","text":"ترتبط المرحلة السالبة بتغير توزيع الضغط وضعف نسبي في التدرج الغربي في بعض الفترات."},{"type":"text","text":"يصف التذبذب القطبي AO نمطاً أوسع لتوزيع الضغط بين القطب والعروض الوسطى في نصف الكرة الشمالي."},{"type":"text","text":"تؤثر هذه الأنماط في احتمالات مسارات المنخفضات والحرارة والهطول في أجزاء من أوروبا وآسيا وأمريكا الشمالية."},{"type":"text","text":"لا تحدد المؤشرات حالة الطقس اليومية بصورة حتمية، بل تصف نمطاً واسع النطاق واحتمالات إقليمية."},{"type":"text","text":"قد تتداخل NAO وAO مع ENSO والأنماط المحيطية والثلجية، ما يغير الاستجابة المتوقعة."},{"type":"text","text":"تستخدم السلاسل الزمنية للمؤشرات والخرائط الشهرية لتحليل العلاقة مع الشذوذات المناخية."},{"type":"text","text":"تختلف قوة العلاقة حسب الفصل والمنطقة والفترة المرجعية، وقد تتغير بمرور الزمن."},{"type":"text","text":"يجب عدم استنتاج سبب مناخي مباشر من ارتباط إحصائي دون تحليل ديناميكي إضافي."},{"type":"text","text":"مثال: مرحلة موجبة من NAO قد ترتبط بشتاء أدفأ ورطب في بعض مناطق شمال أوروبا، مع اختلاف الأثر في جنوب القارة."},{"type":"callout","text":"خلاصة: مؤشرات التذبذب تساعد على وصف الخلفية المناخية واسعة النطاق ولا تستبدل التوقع الإقليمي."}]}',1200,55,'["شرح مؤشري NAO وAO","فهم تغير توزيع الضغط","ربط الأنماط بمسارات الأنظمة الجوية"]','الدوران العام والمناخ الإقليمي'),
('madden-julian-oscillation','تذبذب مادن-جوليان والحركة المدارية داخل الموسمية','انتقال مناطق الحمل والرطوبة في المدار وتأثيرها في النشاط المطري.','{"blocks":[{"type":"text","text":"تذبذب مادن-جوليان MJO نمط من التباين داخل الموسمي في الحمل الحراري والرياح والرطوبة فوق المناطق المدارية."},{"type":"text","text":"يتضمن النمط مناطق حمل نشط ومناطق حمل مكبوت تنتقل غالباً شرقاً عبر المحيط الهندي والهادئ."},{"type":"text","text":"تستغرق الدورة عادة عدة أسابيع إلى نحو شهرين، مع تغير سرعتها وقوتها من حالة لأخرى."},{"type":"text","text":"يؤثر MJO في توزيع السحب والهطول والرياح المدارية وقد يعدل احتمالات تطور أنظمة جوية في مناطق بعيدة."},{"type":"text","text":"تتفاعل المرحلة المدارية مع الرياح والدوامية والرطوبة والأنظمة الموسمية الإقليمية."},{"type":"text","text":"تستخدم مؤشرات الطور والسعة لتحديد موقع النمط وقوته وفق مخططات تشغيلية معروفة."},{"type":"text","text":"تتغير آثار MJO بحسب الموسم والمنطقة، وقد يتفاعل مع ENSO ويعدل بعض تأثيراته."},{"type":"text","text":"يساعد تحليل MJO في التوقعات الممتدة لأسابيع، لكنه لا يحدد توقيت حدث محلي دقيق بمفرده."},{"type":"text","text":"قد تضعف الإشارة أو تتوقف أو تتغير بنيتها أثناء انتقالها عبر أحواض المحيطات والقارات."},{"type":"text","text":"تستخدم بيانات السحب والرياح والرطوبة ومخرجات النماذج لتتبع تطور النمط."},{"type":"text","text":"مثال: انتقال طور نشط فوق المحيط الهندي قد يغير احتمالات النشاط المطري في مناطق مدارية خلال الأسابيع التالية."},{"type":"callout","text":"خلاصة: MJO نمط داخل موسمي مهم يربط الحمل المداري بالتوقعات الممتدة لعدة أسابيع."}]}',1210,55,'["شرح MJO","فهم الانتشار شرقاً","تمييز التغير داخل الموسمي عن ENSO"]','الدوران العام والمناخ الإقليمي'),
('regional-climatology-arid-regions','مناخ المناطق الجافة وشبه الجافة','التوازن المائي والحراري والتباين اليومي والموسمي في البيئات الجافة.','{"blocks":[{"type":"text","text":"تتميز المناطق الجافة بانخفاض الهطول السنوي مقارنة بالطلب التبخري، مع تفاوت كبير في التوزيع الزمني والمكاني."},{"type":"text","text":"تختلف البيئات الجافة عن شبه الجافة وفق مؤشرات مناخية تعتمد على نسبة الهطول إلى التبخر-النتح المحتمل."},{"type":"text","text":"قد يكون التباين الحراري اليومي كبيراً بسبب صفاء السماء وانخفاض الرطوبة وتغير التبريد الإشعاعي."},{"type":"text","text":"تتأثر الأمطار في المناطق الجافة بالمنخفضات والجبهات والاضطرابات المدارية والرفع التضاريسي والحمل المحلي."},{"type":"text","text":"قد تسهم العواصف الحملية قصيرة العمر في جزء كبير من الهطول السنوي في بعض الأقاليم."},{"type":"text","text":"تزيد التربة الجافة والغطاء النباتي المحدود قابلية إثارة الغبار عند توفر الرياح المناسبة."},{"type":"text","text":"تؤثر الواحات والمدن والسواحل والجبال في مناخ محلي يختلف عن البيئة الصحراوية المحيطة."},{"type":"text","text":"تؤدي فترات الجفاف الطويلة إلى تغير رطوبة التربة والغطاء النباتي والتبخر الفعلي."},{"type":"text","text":"تتطلب دراسة المناخ الجاف سجلات طويلة بسبب التباين الكبير بين السنوات."},{"type":"text","text":"تستخدم مؤشرات الجفاف والهطول الشديد والحرارة لتقييم المخاطر والموارد في هذه البيئات."},{"type":"text","text":"مثال: قد يسجل موقع جبلي داخل إقليم جاف هطولاً أعلى بكثير من سهل قريب بسبب الرفع التضاريسي."},{"type":"callout","text":"خلاصة: مناخ المناطق الجافة يجمع ندرة الماء وتطرف الحرارة وتبايناً مكانياً وزمنياً ملحوظاً."}]}',1220,55,'["تمييز الجفاف المناخي","فهم التباين الحراري اليومي","شرح مصادر الهطول في الأقاليم الجافة"]','مناخ الأقاليم والأنماط المحلية'),
('mediterranean-climate-and-weather-regimes','مناخ البحر المتوسط وأنماط الطقس الإقليمية','الشتاء المطير والصيف الجاف وتأثير دوران العروض الوسطى والمرتفع شبه المداري.','{"blocks":[{"type":"text","text":"يتميز مناخ البحر المتوسط تقليدياً بصيف حار أو دافئ جاف وشتاء معتدل أو بارد ممطر نسبياً."},{"type":"text","text":"يرتبط الجفاف الصيفي بامتداد المرتفع شبه المداري والهبوط الجوي وضعف الاضطرابات في كثير من مناطق الحوض."},{"type":"text","text":"يزداد نشاط المنخفضات والجبهات في الموسم البارد مع انتقال مسارات الرياح الغربية نحو العروض الأدنى."},{"type":"text","text":"تؤثر التضاريس الساحلية والجبلية في توزيع المطر والثلوج والرياح بين أجزاء الحوض."},{"type":"text","text":"تختلف كمية الهطول من الغرب إلى الشرق ومن الساحل إلى الداخل، ولا يمثل المتوسط الإقليمي كل موقع."},{"type":"text","text":"قد تؤدي المنخفضات المتوسطية إلى هطول غزير ورياح قوية وانخفاض درجات الحرارة وفق مسارها وبنيتها."},{"type":"text","text":"تؤثر الأنظمة المدارية المتوسطة أو المنخفضات المعزولة في بعض الحالات، لكنها ليست النمط المعتاد للموسم كله."},{"type":"text","text":"تسهم حرارة سطح البحر في تعديل الرطوبة والاستقرار والطقس الساحلي، خاصة عند مرور هواء أبرد فوق المياه الأدفأ."},{"type":"text","text":"تستخدم خرائط الضغط والارتفاع والرطوبة وحرارة البحر لفهم الحالات الشتوية المؤثرة."},{"type":"text","text":"قد تختلف مواسم المطر بين السنوات بفعل الأنماط الدورانية واسعة النطاق مثل NAO وغيرها."},{"type":"text","text":"مثال: قد يتسبب أخدود علوي فوق غرب المتوسط في تشكل منخفض وهطول على أجزاء من الساحل والجبال وفق مسار الرطوبة والرفع."},{"type":"callout","text":"خلاصة: مناخ البحر المتوسط نتاج تفاعل الموسمية والمرتفع شبه المداري والمنخفضات والتضاريس والبحر."}]}',1230,55,'["شرح خصائص مناخ البحر المتوسط","فهم الموسمية المطرية","تحليل الأنظمة الجوية المؤثرة"]','مناخ الأقاليم والأنماط المحلية'),
('koppen-climate-classification','تصنيف كوبن للمناخ والأقاليم الحرارية والمطرية','مبادئ تصنيف الأقاليم المناخية اعتماداً على الحرارة والهطول والموسمية.','{"blocks":[{"type":"text","text":"يقسم تصنيف كوبن المناخات إلى مجموعات رئيسة اعتماداً على أنماط الحرارة والهطول والموسمية والغطاء النباتي المرتبط بها."},{"type":"text","text":"تشمل المجموعة A المناخات المدارية ذات الحرارة المرتفعة طوال العام وفق حدود التصنيف."},{"type":"text","text":"تشمل المجموعة B المناخات الجافة التي تحدد أساساً بالعلاقة بين الهطول والطلب التبخري."},{"type":"text","text":"تشمل المجموعة C المناخات المعتدلة ذات شتاء غير شديد البرودة وفق حدود حرارية محددة."},{"type":"text","text":"تشمل المجموعة D المناخات القارية الباردة ذات التباين الموسمي الكبير في درجات الحرارة."},{"type":"text","text":"تشمل المجموعة E مناخات المناطق القطبية التي يكون الصيف فيها بارداً وفق معايير التصنيف."},{"type":"text","text":"تضيف الرموز الفرعية معلومات عن موسمية المطر مثل الجفاف الصيفي أو الشتوي أو انتظام الهطول."},{"type":"text","text":"تستخدم درجات الحرارة الشهرية والهطول الشهري والسنوي لتحديد الفئة وفق قواعد كمية."},{"type":"text","text":"تختلف خرائط كوبن بحسب فترة البيانات ودقتها وطريقة احتساب الحدود والمناطق الانتقالية."},{"type":"text","text":"التصنيف أداة وصفية مفيدة للمقارنة، لكنه لا يصف وحده التطرفات اليومية أو التباين المحلي الدقيق."},{"type":"text","text":"مثال: قد يصنف ساحل معتدل ضمن مناخ متوسطي بينما تصنف منطقة داخلية قريبة ضمن فئة مختلفة بسبب التباين الحراري والهطولي."},{"type":"callout","text":"خلاصة: تصنيف كوبن يوفر لغة موحدة لوصف الأقاليم المناخية مع ضرورة فهم معاييره وحدوده."}]}',1240,55,'["شرح فكرة تصنيف كوبن","تمييز المجموعات المناخية","فهم حدود التصنيف"]','مناخ الأقاليم والأنماط المحلية'),
('climate-variability-and-teleconnections','التذبذب المناخي والاتصالات المناخية بعيدة المدى','التباين الطبيعي وأنماط الاتصال بين الأحواض والمناطق المناخية.','{"blocks":[{"type":"text","text":"يشير التباين المناخي إلى تغير المناخ حول متوسطه على مقاييس زمنية تمتد من مواسم إلى عقود."},{"type":"text","text":"قد ينتج التباين من تفاعلات المحيط والغلاف الجوي والجليد واليابسة والعوامل الخارجية."},{"type":"text","text":"الاتصال المناخي بعيد المدى Teleconnection علاقة مكانية بين تغيرات جوية أو محيطية متباعدة ترتبط بنمط ديناميكي مشترك."},{"type":"text","text":"تعد ENSO وNAO وAO وMJO أمثلة لأنماط تؤثر في احتمالات المناخ على مناطق واسعة."},{"type":"text","text":"قد تظهر الاستجابة الإقليمية متأخرة زمنياً عن تغير المحيط أو المؤشر المناخي، ويختلف التأخر حسب النمط والمنطقة."},{"type":"text","text":"لا يعني الارتباط الإحصائي وحده وجود علاقة سببية مباشرة، ويجب فحص الآلية الفيزيائية واستقرار العلاقة عبر الزمن."},{"type":"text","text":"تتداخل عدة أنماط في الموسم نفسه، وقد يعزز بعضها أثر بعض أو يضعفه."},{"type":"text","text":"تستخدم مؤشرات الدوران وحرارة سطح البحر والضغط والرياح لتحليل الأنماط بعيدة المدى."},{"type":"text","text":"تساعد خرائط الارتباط والانحدار المركب في استكشاف العلاقات، لكنها تحتاج اختبارات دلالة ومعالجة تعدد المقارنات."},{"type":"text","text":"قد تتغير الاتصالات المناخية مع تغير خط الأساس والمناخ، لذلك يجب عدم افتراض ثبات العلاقات التاريخية."},{"type":"text","text":"مثال: دراسة ارتباط ENSO بمطر إقليم معين تتطلب تقسيم النتائج حسب الموسم وفحص الفترات المختلفة والآلية المحتملة."},{"type":"callout","text":"خلاصة: تحليل التذبذب والاتصالات يوسع فهم الخلفية المناخية، لكنه يحتاج حذراً في تفسير السببية والتوقع."}]}',1250,55,'["تمييز التذبذب المناخي عن الاتجاه","شرح الاتصالات بعيدة المدى","قراءة مؤشرات المناخ واسعة النطاق"]','مناخ الأقاليم والأنماط المحلية'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'الدوران العام والمناخ الإقليمي' then u1.id when 'مناخ الأقاليم والأنماط المحلية' then u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الدوران العام والمناخ الإقليمي والتذبذبات المناخية',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;